from decimal import Decimal

HOECHSTRABATT = Decimal("0.30")


def gesamtrabatt(rabatte):
    """Mehrere Rabatte wirken nacheinander: 10 % und 10 % sind zusammen 19 %.
    Zusammen sind es hoechstens 30 %. Rabatte kommen als Text, etwa "0.10"."""
    rest = Decimal(1)
    for r in rabatte:
        rest -= Decimal(r)
    return min(1 - rest, HOECHSTRABATT)

