from decimal import Decimal

from .geld import cent
from .rabatt import gesamtrabatt

MWST = {"normal": Decimal("0.19"), "ermaessigt": Decimal("0.07")}


def summe(posten, rabatte=()):
    """Bruttosumme einer Rechnung.

    posten: Liste von (Nettopreis als Text, Menge, Steuersatz), der Satz ist
    "normal" oder "ermaessigt". Der Rabatt gilt fuer den Nettobetrag. Je Satz
    wird der rabattierte Nettobetrag auf Cent gerundet und darauf die Steuer
    dieses Satzes berechnet, ebenfalls auf Cent gerundet."""
    netto = {}
    for preis, menge, satz in posten:
        netto[satz] = netto.get(satz, 0) + Decimal(preis) * menge
    faktor = 1 - gesamtrabatt(rabatte)
    brutto = Decimal(0)
    for satz, betrag in netto.items():
        rabattiert = cent(betrag * faktor)
        brutto += rabattiert + cent(rabattiert * MWST["normal"])
    return cent(brutto)

