import re

GRENZE = 40
UMLAUTE = {"ä": "ae", "ö": "oe", "ü": "ue", "ß": "ss"}


def _umschreiben(text):
    return "".join(UMLAUTE.get(z, z) for z in text)


def slug(text, trenner="-"):
    """Macht aus einem Titel einen Teil einer Adresse, hoechstens GRENZE Zeichen,
    gekuerzt an einer Wortgrenze; die Woerter verbindet `trenner`."""
    text = _umschreiben(text.lower()).replace(" ", "-")
    text = re.sub(r"[^a-z0-9-]", "", text)
    text = re.sub(r"-+", "-", text).strip("-")
    if len(text) > GRENZE:
        text = text[:GRENZE + 1].rsplit("-", 1)[0]
    return text.replace("-", trenner)

