import datetime
import sys

from . import speicher

HILFE = "Befehle: add TEXT [--prio P] [--bis DATUM], done ID, list [--offen] [--sort prio] [--faellig DATUM]"
PRIOS = ("hoch", "mittel", "niedrig")


class Fehler(Exception):
    pass


def datum(text):
    try:
        return datetime.date.fromisoformat(text).isoformat()
    except ValueError:
        raise Fehler(f"kein Datum: {text}")


def optionen(rest, erlaubt):
    werte, frei, i = {}, [], 0
    while i < len(rest):
        a = rest[i]
        if a.startswith("--"):
            name = a[2:]
            if name not in erlaubt:
                raise Fehler(f"unbekannte Option {a}")
            if erlaubt[name]:
                if i + 1 >= len(rest):
                    raise Fehler(f"{a} braucht einen Wert")
                werte[name] = rest[i + 1]
                i += 2
                continue
            werte[name] = True
        else:
            frei.append(a)
        i += 1
    return werte, frei


def zeile(e):
    s = f"[{'x' if e['erledigt'] else ' '}] {e['id']} {e['text']}"
    zusatz = []
    if e.get("prio", "mittel") != "mittel":
        zusatz.append(e["prio"])
    if e.get("bis"):
        zusatz.append(f"bis {e['bis']}")
    return s + (f" ({', '.join(zusatz)})" if zusatz else "")


def ausfuehren(argv):
    try:
        return _ausfuehren(argv)
    except Fehler as f:
        print(f, file=sys.stderr)
        return 2


def _ausfuehren(argv):
    if not argv:
        print(HILFE, file=sys.stderr)
        return 2
    eintraege = speicher.laden()
    befehl, rest = argv[0], argv[1:]
    if befehl == "add":
        werte, frei = optionen(rest, {"prio": True, "bis": True})
        if not frei:
            raise Fehler("add braucht einen Text")
        prio = werte.get("prio", "mittel")
        if prio not in PRIOS:
            raise Fehler(f"unbekannte Prioritaet {prio}")
        neu = max((e["id"] for e in eintraege), default=0) + 1
        e = {"id": neu, "text": " ".join(frei), "erledigt": False, "prio": prio}
        if "bis" in werte:
            e["bis"] = datum(werte["bis"])
        eintraege.append(e)
        speicher.speichern(eintraege)
        print(neu)
        return 0
    if befehl == "done":
        for e in eintraege:
            if rest and str(e["id"]) == rest[0]:
                e["erledigt"] = True
                speicher.speichern(eintraege)
                return 0
        print("keine solche Aufgabe", file=sys.stderr)
        return 1
    if befehl == "list":
        werte, frei = optionen(rest, {"offen": False, "sort": True, "faellig": True})
        if frei:
            raise Fehler(f"unerwartet: {' '.join(frei)}")
        auswahl = list(eintraege)
        if werte.get("offen"):
            auswahl = [e for e in auswahl if not e["erledigt"]]
        if "faellig" in werte:
            stichtag = datum(werte["faellig"])
            auswahl = [e for e in auswahl if not e["erledigt"] and e.get("bis") and e["bis"] < stichtag]
        if "sort" in werte:
            if werte["sort"] != "prio":
                raise Fehler(f"unbekannte Sortierung {werte['sort']}")
            auswahl.sort(key=lambda e: (PRIOS.index(e.get("prio", "mittel")), e["id"]))
        for e in auswahl:
            print(zeile(e))
        return 0
    print(HILFE, file=sys.stderr)
    return 2

