def abstand(a, b):
    """Levenshtein-Abstand: Einfuegen, Loeschen und Ersetzen kosten je 1."""
    vorher = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        jetzt = [i]
        for j, y in enumerate(b, 1):
            jetzt.append(min(vorher[j] + 1, jetzt[j - 1] + 1, vorher[j - 1] + (x != y)))
        vorher = jetzt
    return vorher[-1]


def paare(woerter):
    """Alle Paare (a, b) verschiedener Woerter mit a < b und Abstand genau 1,
    sortiert. Doppelte Woerter in der Eingabe zaehlen einmal."""
    einzeln = sorted(set(woerter))
    gefunden = []
    for i, a in enumerate(einzeln):
        for b in einzeln[i + 1:]:
            if abstand(a, b) == 1:
                gefunden.append((a, b))
    return gefunden

